 from scipy import ndimage
 l,n=ndimage.label(mask)
 slices=ndimage.find_objects(l)
 comps=[]
 for i,s in enumerate(slices,1):
  if s:
   area=int((l[s]==i).sum())
   if area>2: comps.append((area,(s[1].start,s[0].start,s[1].stop,s[0].stop)))
 print('components', comps)
except Exception as e: print('nd err',e)
